//! Python-compatible number formatting and parsing (round, str(float), %g, float(str), %).
//!
//! Each helper reproduces CPython 3 exactly for finite and non-finite inputs, and is
//! checked against `rust/fixtures/data/pyfmt.json` (generated by
//! `rust/fixtures/gen/pyfmt.py`). Where Python *raises*, the helper documents what it
//! returns instead; callers that must distinguish use the `try_` variant.
//!
//! Rust's `{:.N}` and `{:.Ne}` formatting is correctly rounded, ties to even on the
//! exact binary value, which is what CPython's `dtoa` does, so the helpers build on it.

/// Python's `str.isspace()` for one character.
///
/// Rust's `char::is_whitespace` (Unicode White_Space) plus U+001C..U+001F, which
/// Python counts as whitespace (they are bidi class B/S) and Rust does not.
pub fn py_is_space(c: char) -> bool {
    c.is_whitespace() || ('\u{1c}'..='\u{1f}').contains(&c)
}

/// Python's `s.strip()` with no argument.
pub fn py_strip(s: &str) -> &str {
    s.trim_matches(py_is_space)
}

/// Python's `round(x, ndigits)` for a float: ties to even on the exact value, then the
/// nearest double to that decimal, sign kept (`round(-0.4, 0)` is `-0.0`).
///
/// Where Python raises `OverflowError` ("rounded value too large to represent", only
/// possible for `ndigits` near -308 on values near the top of the range) this returns
/// the infinity of the same sign; [`try_py_round`] reports it instead.
pub fn py_round(x: f64, ndigits: i32) -> f64 {
    match try_py_round(x, ndigits) {
        Ok(v) => v,
        Err(_) => f64::INFINITY.copysign(x),
    }
}

/// [`py_round`], with Python's `OverflowError` as `Err`.
pub fn try_py_round(x: f64, ndigits: i32) -> Result<f64, &'static str> {
    // CPython's NDIGITS_MAX and NDIGITS_MIN (floatobject.c).
    const NDIGITS_MAX: i32 = 323;
    const NDIGITS_MIN: i32 = -308;
    if !x.is_finite() || x == 0.0 {
        return Ok(x);
    }
    if ndigits > NDIGITS_MAX {
        return Ok(x);
    }
    if ndigits < NDIGITS_MIN {
        return Ok(0.0 * x);
    }
    let rounded = if ndigits >= 0 {
        let prec = ndigits as usize;
        let text = format!("{:.prec$}", x);
        text.parse::<f64>().unwrap_or(f64::NAN)
    } else {
        round_negative(x, (-ndigits) as usize)
    };
    if rounded.is_infinite() {
        return Err("rounded value too large to represent");
    }
    Ok(rounded)
}

/// `round(x, -k)` for k >= 1: half-even rounding of the exact value to a multiple of
/// 10**k, done on the exact decimal digits of the integer part plus a sticky bit for
/// the fraction.
fn round_negative(x: f64, k: usize) -> f64 {
    let ax = x.abs();
    let int_part = ax.trunc();
    let sticky_frac = ax != int_part;
    // `{:.0}` of an integral double is its exact decimal digits.
    let digits: Vec<u8> = format!("{:.0}", int_part).into_bytes();
    let n = digits.len();
    let mut keep: Vec<u8>;
    let round_up;
    if n < k {
        keep = Vec::new();
        round_up = false;
    } else {
        keep = digits[..n - k].to_vec();
        let first = digits[n - k];
        let rest_nonzero = digits[n - k + 1..].iter().any(|&d| d != b'0') || sticky_frac;
        let last_odd = keep.last().map(|&d| (d - b'0') % 2 == 1).unwrap_or(false);
        round_up = first > b'5' || (first == b'5' && (rest_nonzero || last_odd));
    }
    if round_up {
        let mut i = keep.len();
        loop {
            if i == 0 {
                keep.insert(0, b'1');
                break;
            }
            i -= 1;
            if keep[i] == b'9' {
                keep[i] = b'0';
            } else {
                keep[i] += 1;
                break;
            }
        }
    }
    let magnitude = if keep.is_empty() {
        0.0
    } else {
        let text = format!("{}e{}", String::from_utf8_lossy(&keep), k);
        text.parse::<f64>().unwrap_or(f64::INFINITY)
    };
    magnitude.copysign(x)
}

/// Python's `round(x)` with no `ndigits`: ties to even, returning an int.
///
/// Python raises on NaN (`ValueError`) and infinity (`OverflowError`); this saturates
/// like `as i64` (NaN gives 0). Use [`try_py_round0`] where that matters.
pub fn py_round0(x: f64) -> i64 {
    x.round_ties_even() as i64
}

/// [`py_round0`], with `Err` naming the exception Python raises, and `Err` for a
/// result outside `i64` (Python's int is unbounded).
pub fn try_py_round0(x: f64) -> Result<i64, &'static str> {
    if x.is_nan() {
        return Err("ValueError");
    }
    if x.is_infinite() {
        return Err("OverflowError");
    }
    to_i64(x.round_ties_even())
}

/// Python's `int(x)` for a float: truncate toward zero.
pub fn try_py_int(x: f64) -> Result<i64, &'static str> {
    if x.is_nan() {
        return Err("ValueError");
    }
    if x.is_infinite() {
        return Err("OverflowError");
    }
    to_i64(x.trunc())
}

fn to_i64(v: f64) -> Result<i64, &'static str> {
    // 2**63 is exactly representable; anything at or above it does not fit.
    if v >= 9_223_372_036_854_775_808.0 || v < -9_223_372_036_854_775_808.0 {
        return Err("out of i64 range");
    }
    Ok(v as i64)
}

/// The shortest round-trip digits of `|x|` and the decimal exponent of the first one,
/// for a finite `x`: `1234.5` gives `("12345", 3)`.
fn shortest_digits(x: f64) -> (String, i32) {
    let text = format!("{:e}", x.abs());
    let (mant, exp) = text.split_once('e').unwrap_or((&text, "0"));
    let digits: String = mant.chars().filter(|c| c.is_ascii_digit()).collect();
    (digits, exp.parse::<i32>().unwrap_or(0))
}

fn exp_suffix(exp: i32) -> String {
    let sign = if exp < 0 { '-' } else { '+' };
    format!("e{sign}{:02}", exp.abs())
}

/// Python's `str(x)` / `repr(x)` / `f"{x}"` for a float.
///
/// Shortest round-trip digits; positional for exponents -4..=15 with a `.0` on
/// integral values, otherwise `1e-05` / `1.5e+16`; `nan`, `inf`, `-inf`.
pub fn py_float_str(x: f64) -> String {
    if x.is_nan() {
        return "nan".to_string();
    }
    if x.is_infinite() {
        return if x > 0.0 { "inf" } else { "-inf" }.to_string();
    }
    let sign = if x.is_sign_negative() { "-" } else { "" };
    let (digits, exp) = shortest_digits(x);
    let decpt = exp + 1;
    let body = if decpt <= -4 || decpt > 16 {
        let mut s = digits[..1].to_string();
        if digits.len() > 1 {
            s.push('.');
            s.push_str(&digits[1..]);
        }
        s.push_str(&exp_suffix(exp));
        s
    } else if decpt <= 0 {
        format!("0.{}{}", "0".repeat((-decpt) as usize), digits)
    } else if decpt as usize >= digits.len() {
        format!("{}{}.0", digits, "0".repeat(decpt as usize - digits.len()))
    } else {
        let (a, b) = digits.split_at(decpt as usize);
        format!("{a}.{b}")
    };
    format!("{sign}{body}")
}

/// Python's `format(x, f".{precision}g")`, `f"{x:.{precision}g}"` and
/// `"%.*g" % (precision, x)`. Precision 0 is treated as 1, as in Python. For the
/// default `:g` / `%g`, pass 6.
pub fn py_g(x: f64, precision: usize) -> String {
    if x.is_nan() {
        return "nan".to_string();
    }
    if x.is_infinite() {
        return if x > 0.0 { "inf" } else { "-inf" }.to_string();
    }
    let p = precision.max(1);
    let sci = format!("{:.prec$e}", x, prec = p - 1);
    let (mant, exp) = sci.split_once('e').unwrap_or((&sci, "0"));
    let exp: i32 = exp.parse().unwrap_or(0);
    if exp >= -4 && (exp as i64) < p as i64 {
        let decimals = (p as i32 - 1 - exp) as usize;
        let fixed = format!("{:.decimals$}", x);
        strip_trailing_zeros(&fixed).to_string()
    } else {
        format!("{}{}", strip_trailing_zeros(mant), exp_suffix(exp))
    }
}

fn strip_trailing_zeros(s: &str) -> &str {
    if s.contains('.') {
        s.trim_end_matches('0').trim_end_matches('.')
    } else {
        s
    }
}

/// Python's `format(x, f".{precision}f")` / `f"{x:.{precision}f}"` / `"%.*f"`.
///
/// Rust's `{:.N}` already agrees for finite values (including `-0`); this only fixes
/// the spelling of NaN and the infinities.
pub fn py_f(x: f64, precision: usize) -> String {
    if x.is_nan() {
        return "nan".to_string();
    }
    if x.is_infinite() {
        return if x > 0.0 { "inf" } else { "-inf" }.to_string();
    }
    format!("{:.precision$}", x)
}

/// Python's float `x % y`: the result takes the sign of `y`, and a zero result is
/// `+0.0` for positive `y` (so `-0.0 % 360.0` is `0.0`, where `rem_euclid` keeps
/// `-0.0`). Python raises `ZeroDivisionError` for `y == 0`; this returns NaN.
pub fn py_mod(x: f64, y: f64) -> f64 {
    if y == 0.0 {
        return f64::NAN;
    }
    let m = x % y;
    if m != 0.0 {
        if (y < 0.0) != (m < 0.0) { m + y } else { m }
    } else {
        0.0f64.copysign(y)
    }
}

/// Python's `float(s)` for a string: surrounding whitespace, an optional sign,
/// `inf`/`infinity`/`nan` in any case, and `_` between digits. `None` where Python
/// raises `ValueError`.
///
/// Known difference: Python also accepts non-ASCII decimal digits (`float("١٢")` is
/// 12.0); this rejects them.
pub fn py_float_parse(s: &str) -> Option<f64> {
    // float() strips ASCII whitespace (" \t\n\v\f\r") and non-ASCII Unicode whitespace,
    // but not U+001C..U+001F, which str.strip() would remove.
    let t = s.trim_matches(|c: char| {
        matches!(c, ' ' | '\t' | '\n' | '\u{0b}' | '\u{0c}' | '\r')
            || (!c.is_ascii() && py_is_space(c))
    });
    let (neg, rest) = match t.as_bytes().first() {
        Some(b'-') => (true, &t[1..]),
        Some(b'+') => (false, &t[1..]),
        _ => (false, t),
    };
    let lower = rest.to_ascii_lowercase();
    if lower == "inf" || lower == "infinity" {
        return Some(if neg {
            f64::NEG_INFINITY
        } else {
            f64::INFINITY
        });
    }
    if lower == "nan" {
        return Some(if neg { -f64::NAN } else { f64::NAN });
    }
    let clean = clean_decimal(rest)?;
    let v = clean.parse::<f64>().ok()?;
    Some(if neg { -v } else { v })
}

/// Validate Python's decimal float grammar (without sign) and drop the underscores.
fn clean_decimal(s: &str) -> Option<String> {
    let b = s.as_bytes();
    let mut i = 0;
    let mut out = String::with_capacity(b.len());

    // digitpart: digit (["_"] digit)*
    fn digitpart(b: &[u8], i: &mut usize, out: &mut String) -> bool {
        if *i >= b.len() || !b[*i].is_ascii_digit() {
            return false;
        }
        out.push(b[*i] as char);
        *i += 1;
        loop {
            if *i < b.len() && b[*i].is_ascii_digit() {
                out.push(b[*i] as char);
                *i += 1;
            } else if *i + 1 < b.len() && b[*i] == b'_' && b[*i + 1].is_ascii_digit() {
                out.push(b[*i + 1] as char);
                *i += 2;
            } else {
                return true;
            }
        }
    }

    let int_ok = digitpart(b, &mut i, &mut out);
    let mut frac_ok = false;
    if i < b.len() && b[i] == b'.' {
        out.push('.');
        i += 1;
        frac_ok = digitpart(b, &mut i, &mut out);
    }
    if !int_ok && !frac_ok {
        return None;
    }
    if i < b.len() && (b[i] == b'e' || b[i] == b'E') {
        out.push('e');
        i += 1;
        if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
            out.push(b[i] as char);
            i += 1;
        }
        if !digitpart(b, &mut i, &mut out) {
            return None;
        }
    }
    if i != b.len() {
        return None;
    }
    if out.ends_with('.') {
        out.push('0');
    }
    if out.starts_with('.') {
        out.insert(0, '0');
    }
    Some(out.replace(".e", ".0e"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn spot_checks() {
        assert_eq!(py_round(2.675, 2), 2.67);
        assert_eq!(py_round(0.5, 0), 0.0);
        assert_eq!(py_round(1.5, 0), 2.0);
        assert!(py_round(-0.4, 0).is_sign_negative());
        assert_eq!(py_round(1250.0, -2), 1200.0);
        assert_eq!(py_round0(2.5), 2);
        assert_eq!(py_float_str(2.0), "2.0");
        assert_eq!(py_float_str(1e-5), "1e-05");
        assert_eq!(py_float_str(1e16), "1e+16");
        assert_eq!(py_float_str(-0.0), "-0.0");
        assert_eq!(py_g(0.0001, 6), "0.0001");
        assert_eq!(py_g(1e-5, 6), "1e-05");
        assert_eq!(py_g(123456789.0, 6), "1.23457e+08");
        assert_eq!(py_f(f64::NAN, 1), "nan");
        assert_eq!(py_mod(-0.0, 360.0).to_bits(), 0.0f64.to_bits());
        assert_eq!(py_mod(-1.0, 360.0), 359.0);
        assert_eq!(py_float_parse(" 1_000.5 "), Some(1000.5));
        assert_eq!(py_float_parse("1__0"), None);
        assert_eq!(py_strip("\u{1c} x \u{a0}"), "x");
    }
}
